"use strict";(self.webpackChunkapenas_um_catolico=self.webpackChunkapenas_um_catolico||[]).push([[881],{276:(a,o,e)=>{e.d(o,{Dw:()=>s,yQ:()=>r});const s=a=>{const o=a.startsWith("/")?a.slice(1):a;return"".concat("/Apenas-um-Catolico","/").concat(o)},r=a=>s("images/santos/".concat(a))},881:(a,o,e)=>{e.d(o,{q:()=>n,P:()=>t});var s=e(555),r=e(276);const i={"sao-francisco":{iconografia:{introducao:"Em pinturas e imagens, S\xe3o Francisco quase sempre aparece com estes sinais:",itens:[{simbolo:"H\xe1bito marrom com capuz",significado:"A roupa dos pobres da \xdambria. Segundo seu primeiro bi\xf3grafo, ele a cortou em forma de cruz."},{simbolo:"Cord\xe3o com tr\xeas n\xf3s",significado:"Os votos de pobreza, castidade e obedi\xeancia dos frades."},{simbolo:"Chagas nas m\xe3os e nos p\xe9s",significado:"Os estigmas que recebeu no monte Alverne, em 1224."},{simbolo:"P\xe1ssaros, lobo e outros animais",significado:"O serm\xe3o aos p\xe1ssaros, o lobo de Gubbio e o amor por toda a cria\xe7\xe3o."},{simbolo:"Caveira",significado:'Lembra a "irm\xe3 morte corporal", que ele tamb\xe9m louvou no C\xe2ntico das Criaturas.'}]},escritos:{introducao:"Francisco escreveu pouco e com simplicidade. O que ficou \xe9 curto e direto:",obras:[{titulo:"C\xe2ntico das Criaturas",texto:"Composto em 1225, j\xe1 doente, no dialeto da \xdambria. \xc9 um dos primeiros textos da literatura italiana."},{titulo:"Regra dos Frades Menores",texto:"A forma de vida da ordem, aprovada pelo papa Hon\xf3rio III em 1223."},{titulo:"Testamento",texto:"Ditado pouco antes de morrer, em 1226, para lembrar aos frades como tudo come\xe7ou."},{titulo:"Louvores ao Deus Alt\xedssimo",texto:"Escritos no Alverne em 1224, num pergaminho que deu a frei Le\xe3o, com o Tau desenhado no verso."}],frases:[{texto:"Depois que o Senhor me deu irm\xe3os, ningu\xe9m me mostrava o que eu devia fazer, mas o pr\xf3prio Alt\xedssimo me revelou que eu devia viver segundo a forma do santo Evangelho.",fonte:"Testamento"},{texto:"Onde h\xe1 caridade e sabedoria, n\xe3o h\xe1 temor nem ignor\xe2ncia.",fonte:"Admoesta\xe7\xf5es, 27"},{texto:"Tu \xe9s santo, Senhor, \xfanico Deus, que fazes maravilhas.",fonte:"Louvores ao Deus Alt\xedssimo"}],mitos:[{frase:'"Pregue o Evangelho em todo tempo; se necess\xe1rio, use palavras."',explicacao:"N\xe3o aparece em nenhum escrito de Francisco nem nas biografias antigas. A ideia mais pr\xf3xima est\xe1 na Regra n\xe3o bulada: todos os frades devem pregar pelas obras."},{frase:'"Senhor, fazei de mim um instrumento de vossa paz."',explicacao:"A ora\xe7\xe3o \xe9 bonita e muito franciscana, mas foi publicada pela primeira vez em 1912, numa revista francesa, sem autor. S\xf3 depois passou a ser atribu\xedda a ele."}]},lugares:[{nome:"Bas\xedlica de S\xe3o Francisco",cidade:"Assis, It\xe1lia",texto:"Guarda o t\xfamulo do santo e os afrescos sobre a sua vida, atribu\xeddos a Giotto."},{nome:"Porci\xfancula",cidade:"Santa Maria dos Anjos, Assis",texto:"A capelinha que ele restaurou e onde morreu, hoje dentro de uma grande bas\xedlica."},{nome:"S\xe3o Dami\xe3o",cidade:"Assis, It\xe1lia",texto:"Onde ouviu o crucifixo falar. Depois virou o convento de Santa Clara."},{nome:"Santu\xe1rio do Alverne",cidade:"La Verna, Toscana",texto:"O monte onde recebeu os estigmas."},{nome:"Santu\xe1rio do Pres\xe9pio",cidade:"Greccio, It\xe1lia",texto:"Onde montou o primeiro pres\xe9pio, no Natal de 1223."}],leituras:[{titulo:"Fioretti de S\xe3o Francisco",autor:"colet\xe2nea do s\xe9culo XIV",texto:"As hist\xf3rias populares sobre ele e os primeiros frades."},{titulo:"Vida de S\xe3o Francisco",autor:"Tom\xe1s de Celano",texto:"A primeira biografia, escrita logo depois da canoniza\xe7\xe3o, em 1228."},{titulo:"Laudato Si'",autor:"papa Francisco, 2015",texto:"Enc\xedclica sobre o cuidado da cria\xe7\xe3o. O t\xedtulo vem do C\xe2ntico das Criaturas."}],novena:{quando:"Tradicionalmente de 25 de setembro a 3 de outubro, v\xe9spera da festa.",dias:[{tema:"A convers\xe3o",reflexao:"Francisco trocou a vida de festas pelo Evangelho. O que Deus est\xe1 pedindo que eu mude?"},{tema:"A pobreza",reflexao:"Ele se desfez de tudo para ser livre. Do que eu poderia me desapegar nesta semana?"},{tema:"A paz",reflexao:"Chamava a todos de irm\xe3o, at\xe9 o sult\xe3o em tempo de guerra. Com quem preciso fazer as pazes?"},{tema:"A cria\xe7\xe3o",reflexao:"Sol, lua, \xe1gua e fogo eram seus irm\xe3os. Como cuido da casa comum?"},{tema:"Os pobres e doentes",reflexao:"O beijo no leproso mudou sua vida. Quem est\xe1 esquecido perto de mim?"},{tema:"A ora\xe7\xe3o",reflexao:"Passava noites rezando nas grutas de Assis. Que tempo reservo hoje s\xf3 para Deus?"},{tema:"A fraternidade",reflexao:'"O Senhor me deu irm\xe3os." Como cuido da minha comunidade e da minha fam\xedlia?'},{tema:"A cruz",reflexao:"Os estigmas mostram um amor que chegou at\xe9 o fim. Como uno minhas dores \xe0s de Cristo?"},{tema:"A alegria",reflexao:"Morreu cantando e chamou a morte de irm\xe3. Onde posso levar alegria hoje?"}],oracao:"S\xe3o Francisco de Assis, que deixastes tudo para seguir a Cristo pobre e crucificado, ensinai-me a viver com simplicidade, a cuidar da cria\xe7\xe3o e a levar a paz por onde eu passar. Apresentai a Deus o pedido que hoje vos confio. Am\xe9m."}},"santa-teresinha":{iconografia:{introducao:"Santa Teresinha \xe9 f\xe1cil de reconhecer. Quase sempre aparece assim:",itens:[{simbolo:"H\xe1bito marrom",significado:"A roupa das carmelitas descal\xe7as, a ordem reformada por Santa Teresa de \xc1vila."},{simbolo:"Capa branca e v\xe9u preto",significado:"O traje das irm\xe3s que j\xe1 fizeram os votos no Carmelo."},{simbolo:"Rosas",significado:'A promessa de "fazer cair uma chuva de rosas" sobre a terra depois de morrer.'},{simbolo:"Crucifixo coberto de rosas",significado:"Une as duas coisas que ela mais amava: Jesus crucificado e o amor que se d\xe1 em pequenos gestos."}]},escritos:{introducao:"Teresinha escreveu por obedi\xeancia \xe0s superioras, sem imaginar que o mundo leria:",obras:[{titulo:"Hist\xf3ria de uma Alma",texto:"Tr\xeas manuscritos escritos entre 1895 e 1897, reunidos e publicados um ano depois da sua morte."},{titulo:"Cartas",texto:"Mais de 260 cartas \xe0 fam\xedlia, \xe0s irm\xe3s e aos dois mission\xe1rios que acompanhava."},{titulo:"Poesias",texto:"Cerca de 50 poemas, muitos feitos a pedido das irm\xe3s para festas do convento."},{titulo:"Recrea\xe7\xf5es piedosas",texto:"Pequenas pe\xe7as de teatro para as irm\xe3s. Numa delas, ela mesma interpretou Joana d'Arc."},{titulo:"\xdaltimas conversas",texto:"Frases anotadas pelas irm\xe3s nos \xfaltimos meses da sua doen\xe7a, em 1897."}],frases:[{texto:"No cora\xe7\xe3o da Igreja, minha M\xe3e, eu serei o Amor.",fonte:"Hist\xf3ria de uma Alma, Manuscrito B"},{texto:"Para mim, a ora\xe7\xe3o \xe9 um impulso do cora\xe7\xe3o, um simples olhar lan\xe7ado ao C\xe9u, um grito de gratid\xe3o e de amor, tanto no meio da prova\xe7\xe3o como no meio da alegria.",fonte:"Manuscrito C, citado no Catecismo da Igreja Cat\xf3lica, 2558"},{texto:"Tudo \xe9 gra\xe7a.",fonte:"\xdaltimas conversas"}]},lugares:[{nome:"Carmelo de Lisieux",cidade:"Lisieux, Fran\xe7a",texto:"O convento onde viveu nove anos e onde est\xe3o as suas rel\xedquias."},{nome:"Bas\xedlica de Santa Teresa",cidade:"Lisieux, Fran\xe7a",texto:"Uma das maiores igrejas da Fran\xe7a no s\xe9culo XX, consagrada em 1954."},{nome:"Les Buissonnets",cidade:"Lisieux, Fran\xe7a",texto:"A casa da fam\xedlia, onde ela cresceu depois da morte da m\xe3e."},{nome:"Casa natal",cidade:"Alen\xe7on, Fran\xe7a",texto:"Onde nasceu, ao lado da igreja em que foi batizada."}],leituras:[{titulo:"Hist\xf3ria de uma Alma",autor:"Santa Teresinha",texto:"O livro que espalhou a pequena via pelo mundo."},{titulo:"Divini Amoris Scientia",autor:"S\xe3o Jo\xe3o Paulo II, 1997",texto:"A carta que a declarou Doutora da Igreja."},{titulo:"C'est la confiance",autor:"papa Francisco, 2023",texto:"Exorta\xe7\xe3o sobre a confian\xe7a no amor de Deus, nos 150 anos do nascimento dela."}],novena:{quando:'A "novena das rosas" costuma ser rezada de 22 a 30 de setembro, mas pode ser feita em qualquer \xe9poca.',dias:[{tema:"A pequena via",reflexao:"Santidade n\xe3o \xe9 fazer coisas grandes, \xe9 fazer tudo com amor. Qual pequena coisa farei hoje por amor?"},{tema:"A confian\xe7a",reflexao:"Ela se via como uma crian\xe7a nos bra\xe7os do Pai. Em que preciso confiar mais?"},{tema:"As coisas de todo dia",reflexao:"Um sorriso para a irm\xe3 dif\xedcil tamb\xe9m \xe9 ora\xe7\xe3o. Quem precisa da minha paci\xeancia?"},{tema:"A fam\xedlia",reflexao:"Seus pais, Lu\xeds e Z\xe9lia, tamb\xe9m s\xe3o santos. Rezo pela minha fam\xedlia."},{tema:"A ora\xe7\xe3o simples",reflexao:'"Um simples olhar lan\xe7ado ao C\xe9u." Posso rezar assim v\xe1rias vezes hoje.'},{tema:"As miss\xf5es",reflexao:"Sem sair do convento, ajudou mission\xe1rios. Por quem rezo que est\xe1 longe?"},{tema:"O sofrimento oferecido",reflexao:"Na doen\xe7a, ofereceu tudo com amor. O que posso oferecer em vez de reclamar?"},{tema:"A miseric\xf3rdia",reflexao:"Confiava mais na miseric\xf3rdia de Deus do que nos pr\xf3prios m\xe9ritos. Deixo Deus me perdoar."},{tema:"A chuva de rosas",reflexao:"Ela prometeu passar o C\xe9u fazendo o bem na terra. Entrego a ela o meu pedido."}],oracao:"Santa Teresinha do Menino Jesus, que prometestes fazer cair uma chuva de rosas sobre a terra, ensinai-me o caminho da confian\xe7a e do amor nas pequenas coisas. Apresentai a Jesus o pedido que hoje vos confio, e, se for da vontade de Deus, mandai-me uma rosa. Am\xe9m."}},"padre-pio":{iconografia:{introducao:"Nas imagens e fotografias, Padre Pio aparece quase sempre com:",itens:[{simbolo:"H\xe1bito capuchinho marrom",significado:"Com capuz pontudo e cord\xe3o branco, como os frades capuchinhos."},{simbolo:"Barba",significado:"Os capuchinhos usavam barba como sinal de pobreza e penit\xeancia."},{simbolo:"Meias-luvas",significado:"Escondiam as chagas das m\xe3os. Ele s\xf3 as tirava para celebrar a Missa."},{simbolo:"Ter\xe7o na m\xe3o",significado:"Rezava muitos ter\xe7os por dia e o chamava de arma para os tempos dif\xedceis."}]},escritos:{introducao:"Padre Pio n\xe3o escreveu livros. O que temos dele s\xe3o cartas e frases guardadas por quem o ouviu:",obras:[{titulo:"Epistol\xe1rio",texto:"As cartas aos seus diretores espirituais e aos filhos espirituais, reunidas em quatro volumes."}],frases:[{texto:"Reze, espere e n\xe3o se preocupe. A preocupa\xe7\xe3o \xe9 in\xfatil. Deus \xe9 misericordioso e ouvir\xe1 a sua ora\xe7\xe3o.",fonte:"Conselho repetido em cartas e conversas"},{texto:"A ora\xe7\xe3o \xe9 a melhor arma que temos; \xe9 a chave que abre o cora\xe7\xe3o de Deus.",fonte:"Frase guardada pelos seus filhos espirituais"}]},milagres:{introducao:"Para a beatifica\xe7\xe3o e a canoniza\xe7\xe3o, a Igreja reconheceu duas curas sem explica\xe7\xe3o m\xe9dica:",itens:[{titulo:"Beatifica\xe7\xe3o, 1999",texto:"A cura de Consiglia de Martino, de Salerno, em 1995, depois de rezar pedindo a intercess\xe3o de Padre Pio."},{titulo:"Canoniza\xe7\xe3o, 2002",texto:"A cura de Matteo Pio Colella, um menino de 7 anos de San Giovanni Rotondo, que estava em coma por meningite em 2000."}]},lugares:[{nome:"Santu\xe1rio de S\xe3o Pio",cidade:"San Giovanni Rotondo, It\xe1lia",texto:"O convento onde viveu 52 anos. A nova igreja, de 2004, foi projetada por Renzo Piano, e o corpo do santo est\xe1 na cripta."},{nome:"Casa Al\xedvio do Sofrimento",cidade:"San Giovanni Rotondo, It\xe1lia",texto:"O hospital que ele fundou em 1956 e que funciona at\xe9 hoje."},{nome:"Casa natal",cidade:"Pietrelcina, It\xe1lia",texto:"A casa simples onde nasceu, numa cidadezinha do sul da It\xe1lia."}],leituras:[{titulo:"Epistol\xe1rio",autor:"S\xe3o Pio de Pietrelcina",texto:"As cartas em que ele acompanha almas, fala da cruz e da confian\xe7a."}],novena:{quando:"Costuma ser rezada de 14 a 22 de setembro. Padre Pio mesmo rezava todos os dias uma novena ao Sagrado Cora\xe7\xe3o pelos que pediam suas ora\xe7\xf5es.",dias:[{tema:"A ora\xe7\xe3o",reflexao:'"A chave que abre o cora\xe7\xe3o de Deus." Reservo um tempo de ora\xe7\xe3o sem pressa.'},{tema:"A confiss\xe3o",reflexao:"Ele passava horas no confession\xe1rio. H\xe1 quanto tempo n\xe3o me confesso?"},{tema:"A Missa",reflexao:"Celebrava a Missa como quem est\xe1 no Calv\xe1rio. Como participo da Missa?"},{tema:"O sofrimento unido a Cristo",reflexao:"Carregou as chagas por 50 anos sem reclamar. Ofere\xe7o a Deus o que me pesa."},{tema:"A obedi\xeancia",reflexao:"Quando foi proibido de celebrar em p\xfablico, obedeceu em sil\xeancio. Onde preciso ceder?"},{tema:"Os doentes",reflexao:"Construiu um hospital para tratar o doente como a Cristo. Rezo por um doente que conhe\xe7o."},{tema:"O anjo da guarda",reflexao:'"Mande-me o seu anjo da guarda." Agrade\xe7o ao meu anjo e pe\xe7o a sua prote\xe7\xe3o.'},{tema:"Nossa Senhora",reflexao:"Rezava o ter\xe7o o dia inteiro. Hoje rezo pelo menos uma dezena com calma."},{tema:"A confian\xe7a",reflexao:'"Reze, espere e n\xe3o se preocupe." Entrego a Deus a minha maior preocupa\xe7\xe3o.'}],oracao:"S\xe3o Pio de Pietrelcina, que carregastes no corpo as chagas de Cristo e passastes a vida no confession\xe1rio e na ora\xe7\xe3o, ensinai-me a rezar, a esperar e a n\xe3o me preocupar. Intercedei junto de Jesus pelo pedido que hoje vos confio. Am\xe9m."}},"nossa-senhora":{iconografia:{introducao:"Cada detalhe das imagens de Maria tem um sentido, quase sempre tirado da B\xedblia:",itens:[{simbolo:"Manto azul",significado:"O c\xe9u e a realeza. Ela \xe9 a Rainha que cobre os filhos com o seu manto."},{simbolo:"Coroa de doze estrelas",significado:"A mulher vestida de sol do Apocalipse (Ap 12,1), e as doze tribos e os doze ap\xf3stolos."},{simbolo:"Lua e serpente sob os p\xe9s",significado:"A vit\xf3ria sobre o mal anunciada no G\xeanesis (Gn 3,15) e a mulher do Apocalipse."},{simbolo:"Raios saindo das m\xe3os",significado:"As gra\xe7as que ela distribui, como na Medalha Milagrosa (1830), a imagem desta p\xe1gina."},{simbolo:"Cora\xe7\xe3o com espada ou rosas",significado:'A profecia de Sime\xe3o: "uma espada traspassar\xe1 a tua alma" (Lc 2,35).'}]},escritos:{introducao:"Maria fala pouco nos Evangelhos. Estas s\xe3o as palavras dela que a B\xedblia guarda:",frases:[{texto:"Como acontecer\xe1 isso, se eu n\xe3o conhe\xe7o homem algum?",fonte:"Lucas 1,34"},{texto:"Eis aqui a serva do Senhor; fa\xe7a-se em mim segundo a tua palavra.",fonte:"Lucas 1,38"},{texto:"A minha alma engrandece o Senhor, e o meu esp\xedrito se alegra em Deus, meu Salvador.",fonte:"Lucas 1,46-47"},{texto:"Meu filho, por que agiste assim conosco? Teu pai e eu te procur\xe1vamos aflitos.",fonte:"Lucas 2,48"},{texto:"Eles n\xe3o t\xeam mais vinho.",fonte:"Jo\xe3o 2,3"},{texto:"Fazei tudo o que ele vos disser.",fonte:"Jo\xe3o 2,5"}]},lugares:[{nome:"Bas\xedlica de Aparecida",cidade:"Aparecida, S\xe3o Paulo",texto:"Guarda a imagem encontrada no rio em 1717. \xc9 apontada como o maior santu\xe1rio mariano do mundo."},{nome:"Bas\xedlica de Guadalupe",cidade:"Cidade do M\xe9xico",texto:"Onde est\xe1 exposto o manto de S\xe3o Juan Diego com a imagem de Maria."},{nome:"Santu\xe1rio de Lourdes",cidade:"Lourdes, Fran\xe7a",texto:"A gruta de Massabielle e a fonte que atrai doentes do mundo inteiro."},{nome:"Santu\xe1rio de F\xe1tima",cidade:"F\xe1tima, Portugal",texto:"A Capelinha das Apari\xe7\xf5es, no lugar exato da azinheira."},{nome:"Bas\xedlica da Anuncia\xe7\xe3o",cidade:"Nazar\xe9, Israel",texto:"Constru\xedda sobre a casa onde, segundo a tradi\xe7\xe3o, Maria recebeu o an\xfancio do anjo."}],leituras:[{titulo:"Redemptoris Mater",autor:"S\xe3o Jo\xe3o Paulo II, 1987",texto:"Enc\xedclica sobre Maria no caminho da Igreja."},{titulo:"Rosarium Virginis Mariae",autor:"S\xe3o Jo\xe3o Paulo II, 2002",texto:"A carta sobre o ter\xe7o que criou os mist\xe9rios luminosos."},{titulo:"Marialis Cultus",autor:"S\xe3o Paulo VI, 1974",texto:"Sobre a devo\xe7\xe3o a Maria e como viv\xea-la bem."}],novena:{quando:"A novena de Nossa Senhora Aparecida \xe9 rezada de 3 a 11 de outubro, mas cada dia acompanha um momento da vida de Maria.",dias:[{tema:"O sim da Anuncia\xe7\xe3o",reflexao:'"Fa\xe7a-se em mim." A que Deus est\xe1 me pedindo um sim?'},{tema:"A visita a Isabel",reflexao:"Maria partiu \xe0s pressas para ajudar. Quem posso visitar ou ajudar?"},{tema:"M\xe3e de Deus em Bel\xe9m",reflexao:"Deus nasceu pobre, nos bra\xe7os de uma m\xe3e. Agrade\xe7o pela minha vida."},{tema:"A busca no Templo",reflexao:"Ela procurou Jesus aflita at\xe9 encontr\xe1-lo. Procuro Jesus quando o perco?"},{tema:"Can\xe1",reflexao:'"Eles n\xe3o t\xeam mais vinho." Conto a Maria o que est\xe1 faltando na minha casa.'},{tema:"Aos p\xe9s da cruz",reflexao:"Ela ficou at\xe9 o fim. Pe\xe7o for\xe7a para quem est\xe1 sofrendo."},{tema:"Pentecostes",reflexao:"Maria rezava com os ap\xf3stolos. Rezo pela Igreja e pelo meu padre."},{tema:"A Assun\xe7\xe3o",reflexao:"Ela j\xe1 est\xe1 no C\xe9u, onde queremos chegar. Pe\xe7o a gra\xe7a da perseveran\xe7a."},{tema:"Aparecida, M\xe3e do Brasil",reflexao:"Encontrada por pescadores pobres. Entrego a ela o meu pedido e o meu pa\xeds."}],oracao:'\xd3 Maria, M\xe3e de Jesus e nossa M\xe3e, que dissestes "fazei tudo o que ele vos disser", ensinai-me a ouvir o vosso Filho e a confiar nele. Cobri com o vosso manto a minha fam\xedlia e apresentai a Deus o pedido que hoje vos confio. Am\xe9m.'}}},t=[{slug:"sao-francisco",nome:"S\xe3o Francisco de Assis",resumo:"Padroeiro dos animais e da ecologia, fundador da Ordem Franciscana.",origem:"Assis, It\xe1lia \xb7 1182\u20131226",festa:"4 de outubro",padroeiro:["It\xe1lia","Ecologia","Animais"],imagem:(0,r.yQ)("sao-francisco-jovem.webp"),posicaoImagem:"center 20%",estilo:"sol",cores:{principal:"#6B4A2E",secundaria:"#4E7A3A",brilho:"#D9A441"},paleta:{claro:{fundo:"#F5EFE3",cartao:"#FFFBF3",texto:"#3B2A1C",suave:"#6E5A47",titulo:"#4A3220",borda:"#E4D7C2",topo:"rgba(58, 38, 22, 0.94)"},escuro:{fundo:"#17110B",cartao:"#221A12",texto:"#EFE6D8",suave:"#BFAE97",titulo:"#F1E2C8",borda:"#3A2C1E",topo:"rgba(23, 17, 11, 0.94)"}},frase:{texto:"Louvado sejas, meu Senhor, com todas as tuas criaturas.",autor:"C\xe2ntico das Criaturas"},historia:["Francisco nasceu em Assis, na It\xe1lia, filho de Pedro Bernardone, um rico comerciante de tecidos. Na juventude sonhava ser cavaleiro e gastava sem medida com festas e amigos.",'Depois de uma pris\xe3o de guerra e de uma longa doen\xe7a, come\xe7ou a procurar outro sentido para a vida. Rezando diante do crucifixo da igrejinha de S\xe3o Dami\xe3o, ouviu: "Francisco, vai e reconstr\xf3i a minha casa, que est\xe1 em ru\xednas".',"Diante do bispo de Assis, devolveu ao pai at\xe9 as roupas do corpo e passou a viver na pobreza, servindo os leprosos e reformando igrejas com as pr\xf3prias m\xe3os. Logo outros jovens quiseram seguir o mesmo caminho, e assim nasceram os Frades Menores.","Chamava o sol, a lua, a \xe1gua e o fogo de irm\xe3os, e via em cada criatura um motivo para louvar a Deus. Dois anos antes de morrer, recebeu os estigmas no monte Alverne."],historias:{titulo:"Hist\xf3rias dos Fioretti",introducao:'Os "Fioretti", as florzinhas de S\xe3o Francisco, guardam os epis\xf3dios que o povo contava sobre ele:',itens:[{ilustracao:"lobo",titulo:"O lobo de Gubbio",texto:"Um lobo aterrorizava a cidade de Gubbio. Francisco foi ao encontro dele, chamou-o de irm\xe3o e fez um pacto: o povo daria comida ao lobo, e o lobo n\xe3o atacaria mais ningu\xe9m. Dizem que ele viveu manso na cidade at\xe9 morrer."},{ilustracao:"passaros",titulo:"O serm\xe3o aos p\xe1ssaros",texto:"Perto de Bevagna, Francisco viu um bando de p\xe1ssaros e come\xe7ou a pregar para eles, lembrando que Deus lhes deu penas, asas e o c\xe9u inteiro. Os p\xe1ssaros ficaram quietos ouvindo at\xe9 ele dar a b\xean\xe7\xe3o."},{ilustracao:"presepio",titulo:"O primeiro pres\xe9pio",texto:"No Natal de 1223, em Greccio, Francisco montou uma manjedoura com feno, um boi e um burro, e celebrou ali a Missa da noite. Queria que todos vissem com os olhos a pobreza em que Jesus nasceu. Assim come\xe7ou a tradi\xe7\xe3o do pres\xe9pio."},{ilustracao:"tau",titulo:"O sinal do Tau",texto:"Francisco assinava suas cartas e aben\xe7oava com o Tau, a \xfaltima letra do alfabeto hebraico, em forma de cruz. Para ele era o sinal dos que se convertem e pertencem a Cristo. O Tau virou o s\xedmbolo dos franciscanos."}]},destaque:{tipo:"cantico",titulo:"O C\xe2ntico das Criaturas",introducao:"J\xe1 doente e quase cego, Francisco comp\xf4s um hino em que chama toda a cria\xe7\xe3o de fam\xedlia. Trechos traduzidos do italiano antigo:",itens:[{icone:"sol",titulo:"Irm\xe3o Sol",texto:"Que \xe9 o dia, e por ele nos iluminas. Ele \xe9 belo e radiante, com grande esplendor."},{icone:"lua",titulo:"Irm\xe3 Lua e as estrelas",texto:"No c\xe9u as formaste claras, preciosas e belas."},{icone:"vento",titulo:"Irm\xe3o Vento",texto:"Pelo ar e pelas nuvens, pelo c\xe9u sereno e por todo tempo."},{icone:"agua",titulo:"Irm\xe3 \xc1gua",texto:"Que \xe9 muito \xfatil e humilde, preciosa e casta."},{icone:"fogo",titulo:"Irm\xe3o Fogo",texto:"Com o qual iluminas a noite. Ele \xe9 belo, alegre, robusto e forte."},{icone:"terra",titulo:"Irm\xe3 e m\xe3e Terra",texto:"Que nos sustenta e governa, e produz frutos diversos, com flores coloridas e ervas."}]},linhaDoTempo:[{ano:"1182",texto:"Nasce em Assis, na It\xe1lia."},{ano:"1205",texto:"Ouve o crucifixo de S\xe3o Dami\xe3o pedir que reconstrua a Igreja."},{ano:"1206",texto:"Renuncia \xe0 heran\xe7a do pai diante do bispo de Assis."},{ano:"1209",texto:"O papa Inoc\xeancio III aprova a forma de vida dos primeiros frades."},{ano:"1223",texto:"Monta o primeiro pres\xe9pio vivo, em Greccio, na noite de Natal."},{ano:"1224",texto:"Recebe os estigmas no monte Alverne."},{ano:"1226",texto:"Morre em 3 de outubro, na Porci\xfancula."},{ano:"1228",texto:"\xc9 canonizado pelo papa Greg\xf3rio IX."},{ano:"1979",texto:"S\xe3o Jo\xe3o Paulo II o proclama padroeiro da ecologia."}],videos:[{id:"YnaV24Z1_Oo",titulo:"A vida de S\xe3o Francisco de Assis"},{id:"DxaqKfATuj4",titulo:"Irm\xe3o Sol e Irm\xe3 Lua"}],oracao:{titulo:"Ora\xe7\xe3o pela paz",nota:"Tradicionalmente atribu\xedda a S\xe3o Francisco.",texto:"Senhor, fazei de mim um instrumento de vossa paz.\nOnde houver \xf3dio, que eu leve o amor;\nonde houver ofensa, que eu leve o perd\xe3o;\nonde houver disc\xf3rdia, que eu leve a uni\xe3o;\nonde houver d\xfavida, que eu leve a f\xe9;\nonde houver erro, que eu leve a verdade;\nonde houver desespero, que eu leve a esperan\xe7a;\nonde houver tristeza, que eu leve a alegria;\nonde houver trevas, que eu leve a luz.\n\xd3 Mestre, fazei que eu procure mais\nconsolar que ser consolado,\ncompreender que ser compreendido,\namar que ser amado.\nPois \xe9 dando que se recebe,\n\xe9 perdoando que se \xe9 perdoado,\ne \xe9 morrendo que se vive para a vida eterna."}},{slug:"santa-teresinha",nome:"Santa Teresinha do Menino Jesus",resumo:"Doutora da Igreja e padroeira das miss\xf5es, mestra da pequena via.",origem:"Alen\xe7on, Fran\xe7a \xb7 1873\u20131897",festa:"1\xba de outubro",padroeiro:["Miss\xf5es","Fran\xe7a"],rotuloPadroeiro:"Padroeira",imagem:(0,r.yQ)("Santa terezinha.jpg"),posicaoImagem:"center 25%",estilo:"rosas",cores:{principal:"#A8456B",secundaria:"#5C4033",brilho:"#E8B4C4"},paleta:{claro:{fundo:"#F8F1EE",cartao:"#FFFCF9",texto:"#33232A",suave:"#76626A",titulo:"#4F2234",borda:"#E7D6D2",topo:"rgba(92, 36, 56, 0.94)"},escuro:{fundo:"#1A0E12",cartao:"#26161C",texto:"#F3E4E8",suave:"#C7A8B1",titulo:"#F6D3DD",borda:"#3E2530",topo:"rgba(26, 14, 18, 0.94)"}},frase:{texto:"Quero passar o meu C\xe9u fazendo o bem sobre a terra.",autor:"Santa Teresinha, 1897"},historia:["Teresa Martin nasceu em Alen\xe7on, na Fran\xe7a, a ca\xe7ula de nove filhos de Lu\xeds e Z\xe9lia Martin, hoje tamb\xe9m santos. Perdeu a m\xe3e aos quatro anos, e a fam\xedlia se mudou para Lisieux.","Desde menina queria ser carmelita. Aos 14 anos, numa peregrina\xe7\xe3o a Roma, chegou a pedir ao papa Le\xe3o XIII licen\xe7a para entrar no Carmelo antes da idade. Entrou no Carmelo de Lisieux aos 15.",'N\xe3o fez nada que o mundo chamaria de grande. Descobriu que a santidade cabe nas pequenas coisas feitas com muito amor e numa confian\xe7a de crian\xe7a em Deus. Chamou isso de "pequena via".','Morreu de tuberculose aos 24 anos. Prometeu "fazer cair uma chuva de rosas" sobre a terra, e por isso \xe9 lembrada com rosas. Seus escritos, reunidos em "Hist\xf3ria de uma Alma", correram o mundo.'],historias:{titulo:"Pequenos epis\xf3dios",introducao:'Alguns momentos que a pr\xf3pria Teresinha contou na "Hist\xf3ria de uma Alma":',itens:[{ilustracao:"florzinha",titulo:"A florzinha de Jesus",texto:'Ela come\xe7a a hist\xf3ria da pr\xf3pria vida contando a hist\xf3ria de "uma florzinha branca": uma flor pequena, plantada por Deus num jardim, que s\xf3 quer alegrar o olhar de Jesus. Por isso ficou conhecida como a Pequena Flor.'},{ilustracao:"elevador",titulo:"O elevador",texto:'Achava-se pequena demais para subir a "escada" da perfei\xe7\xe3o. Lembrou dos elevadores, novidade da \xe9poca, e descobriu o seu: "o elevador que deve me elevar at\xe9 o C\xe9u s\xe3o os vossos bra\xe7os, \xf3 Jesus".'},{ilustracao:"missoes",titulo:"Mission\xe1ria sem sair do convento",texto:"Nunca saiu do Carmelo, mas rezava e se oferecia pelos mission\xe1rios. Acompanhou por cartas dois deles, um seminarista e um padre que partiu para a China. Por isso a Igreja a declarou padroeira das miss\xf5es."},{ilustracao:"natal",titulo:"O Natal de 1886",texto:"Aos 13 anos, depois da Missa do Galo, ouviu o pai dizer que era o \xfaltimo ano dos sapatinhos de presente na lareira. Em vez de chorar, como sempre fazia, sorriu. Ela chamou aquela noite de sua convers\xe3o: ali ganhou for\xe7a para amar sem se fechar em si."}]},destaque:{tipo:"pequenaVia",titulo:"A pequena via",introducao:"O caminho que Teresinha ensinou para quem acha que a santidade \xe9 coisa para gente grande:",itens:[{titulo:"Fazer as pequenas coisas com amor",texto:"Um sorriso, uma tarefa bem feita, um sil\xeancio paciente. Nada \xe9 pequeno quando \xe9 feito por amor."},{titulo:"Confiar como uma crian\xe7a",texto:"N\xe3o depender das pr\xf3prias for\xe7as, mas se deixar levar por Deus como um filho nos bra\xe7os do pai."},{titulo:"Oferecer o que custa",texto:"Transformar em oferta os pequenos sacrif\xedcios do dia, sem fazer alarde."},{titulo:"Amar onde Deus nos p\xf4s",texto:"Sem esperar outro lugar ou outra vida: a santidade come\xe7a no lugar de hoje."}]},linhaDoTempo:[{ano:"1873",texto:"Nasce em 2 de janeiro, em Alen\xe7on."},{ano:"1877",texto:"Morre a m\xe3e, Z\xe9lia; a fam\xedlia se muda para Lisieux."},{ano:"1886",texto:"Na noite de Natal, vive o que chamou de sua convers\xe3o."},{ano:"1887",texto:"Em Roma, pede ao papa Le\xe3o XIII para entrar no Carmelo."},{ano:"1888",texto:"Entra no Carmelo de Lisieux, aos 15 anos."},{ano:"1897",texto:"Morre em 30 de setembro, aos 24 anos."},{ano:"1898",texto:'\xc9 publicada a "Hist\xf3ria de uma Alma".'},{ano:"1925",texto:"\xc9 canonizada pelo papa Pio XI."},{ano:"1927",texto:"\xc9 proclamada padroeira das miss\xf5es."},{ano:"1997",texto:"S\xe3o Jo\xe3o Paulo II a declara Doutora da Igreja."}],oracao:{titulo:"Ora\xe7\xe3o a Santa Teresinha",texto:"Santa Teresinha do Menino Jesus,\nque encontrastes o caminho do C\xe9u nas coisas pequenas,\nensinai-me a confiar em Deus como uma crian\xe7a\ne a fazer com amor cada tarefa deste dia.\nDeixai cair sobre mim e sobre os que amo\numa das rosas que prometestes,\ne intercedei por n\xf3s junto de Jesus.\nAm\xe9m."}},{slug:"padre-pio",nome:"S\xe3o Padre Pio de Pietrelcina",resumo:"Frade capuchinho, confessor incans\xe1vel e estigmatizado.",origem:"Pietrelcina, It\xe1lia \xb7 1887\u20131968",festa:"23 de setembro",padroeiro:["Volunt\xe1rios da Defesa Civil (It\xe1lia)"],imagem:(0,r.yQ)("Padre-Pio.webp"),posicaoImagem:"center 20%",estilo:"vela",cores:{principal:"#8B2E2E",secundaria:"#4A3121",brilho:"#E0B25A"},paleta:{claro:{fundo:"#15100C",cartao:"#211913",texto:"#EDE3D6",suave:"#B9A893",titulo:"#F1D9A8",borda:"#3A2C21",topo:"rgba(21, 16, 12, 0.94)",modo:"escuro"},escuro:{fundo:"#15100C",cartao:"#211913",texto:"#EDE3D6",suave:"#B9A893",titulo:"#F1D9A8",borda:"#3A2C21",topo:"rgba(21, 16, 12, 0.94)",modo:"escuro"}},frase:{texto:"Reze, espere e n\xe3o se preocupe.",autor:"Padre Pio"},historia:["Francesco Forgione nasceu numa fam\xedlia pobre de camponeses em Pietrelcina, no sul da It\xe1lia. Aos 15 anos entrou para os frades capuchinhos e recebeu o nome de Pio.","Foi ordenado padre em 1910 e, alguns anos depois, chegou ao convento de San Giovanni Rotondo, onde passaria o resto da vida.","Passava horas no confession\xe1rio e incentivou os grupos de ora\xe7\xe3o. Tamb\xe9m construiu um grande hospital, a Casa Al\xedvio do Sofrimento, para cuidar dos doentes com dignidade.","Entre 1931 e 1933, a Santa S\xe9 o proibiu de celebrar em p\xfablico e de atender confiss\xf5es. Ele obedeceu em sil\xeancio. A proibi\xe7\xe3o foi retirada, e sua fama de santidade s\xf3 cresceu."],chagas:{titulo:"As chagas",texto:["Na manh\xe3 de 20 de setembro de 1918, depois da Missa, Padre Pio rezava diante de um crucifixo no coro da igreja de San Giovanni Rotondo. Quando voltou a si, tinha nas m\xe3os, nos p\xe9s e no lado as feridas de Cristo: os estigmas.","Ele n\xe3o as exibia. Pediu a Deus que as tornasse invis\xedveis, guardando apenas a dor, e cobria as m\xe3os com meias-luvas marrons, que s\xf3 tirava para celebrar a Missa.","As feridas foram examinadas por m\xe9dicos e investigadas pela Igreja durante anos. Sangraram por cinquenta anos e, nos dias antes da sua morte, em 1968, desapareceram sem deixar cicatriz."],fatos:[{numero:"1918",rotulo:"ano em que as chagas apareceram"},{numero:"50",rotulo:"anos carregando as feridas"},{numero:"5",rotulo:"chagas: m\xe3os, p\xe9s e lado"}]},historias:{titulo:"O dia a dia do frade",introducao:"Muito do que se conta de Padre Pio aconteceu em San Giovanni Rotondo:",itens:[{ilustracao:"confessionario",titulo:"O confession\xe1rio",texto:"Atendia confiss\xf5es por at\xe9 dez horas por dia. A procura era tanta que, nos anos 1950, era preciso pegar senha para se confessar com ele. Muitos contavam que ele lia o cora\xe7\xe3o de quem chegava."},{ilustracao:"hospital",titulo:"A Casa Al\xedvio do Sofrimento",texto:'Inaugurado em 1956 com doa\xe7\xf5es do mundo inteiro, o hospital nasceu para tratar os doentes "como se tratasse o pr\xf3prio Cristo". Hoje \xe9 um dos grandes hospitais do sul da It\xe1lia.'},{ilustracao:"terco",titulo:"O ter\xe7o na m\xe3o",texto:'Rezava muitos ter\xe7os por dia e chamava o ros\xe1rio de "a arma" para os tempos dif\xedceis. Atendendo a um pedido do papa Pio XII durante a Segunda Guerra, incentivou os Grupos de Ora\xe7\xe3o, que hoje existem em v\xe1rios pa\xedses.'},{ilustracao:"anjo",titulo:'"Mande-me o seu anjo da guarda"',texto:"Tinha uma devo\xe7\xe3o enorme ao anjo da guarda. A quem n\xe3o podia ir at\xe9 San Giovanni Rotondo, dizia: quando precisar de mim, mande-me o seu anjo da guarda."}]},destaque:{tipo:"conselhos",titulo:"Tr\xeas palavras para o dia a dia",introducao:"O conselho mais conhecido de Padre Pio cabe numa frase s\xf3:",itens:[{titulo:"Reze",texto:"A ora\xe7\xe3o \xe9 a chave que abre o cora\xe7\xe3o de Deus. Comece e termine o dia falando com Ele."},{titulo:"Espere",texto:"Confie que Deus age no tempo dele, mesmo quando nada parece mudar."},{titulo:"N\xe3o se preocupe",texto:"A preocupa\xe7\xe3o n\xe3o muda o amanh\xe3. Entregue a Deus o que n\xe3o est\xe1 nas suas m\xe3os."}]},linhaDoTempo:[{ano:"1887",texto:"Nasce em 25 de maio, em Pietrelcina."},{ano:"1903",texto:"Entra para os frades capuchinhos e recebe o nome de Pio."},{ano:"1910",texto:"\xc9 ordenado sacerdote."},{ano:"1916",texto:"Chega ao convento de San Giovanni Rotondo."},{ano:"1918",texto:"Recebe os estigmas, em 20 de setembro."},{ano:"1931",texto:"A Santa S\xe9 restringe seu minist\xe9rio; ele obedece at\xe9 1933."},{ano:"1956",texto:"Inaugura o hospital Casa Al\xedvio do Sofrimento."},{ano:"1968",texto:"Morre em 23 de setembro."},{ano:"2002",texto:"\xc9 canonizado por S\xe3o Jo\xe3o Paulo II."}],oracao:{titulo:"Fica comigo, Senhor",nota:"In\xedcio da ora\xe7\xe3o que Padre Pio rezava depois da comunh\xe3o, traduzido do italiano.",texto:"Fica comigo, Senhor,\nporque preciso da tua presen\xe7a para n\xe3o te esquecer.\nTu sabes com que facilidade eu te abandono.\nFica comigo, Senhor,\nporque sou fraco e preciso da tua for\xe7a\npara n\xe3o cair tantas vezes.\nFica comigo, Senhor,\nporque tu \xe9s a minha vida,\ne sem ti me falta o fervor."}},{slug:"nossa-senhora",nome:"Nossa Senhora",resumo:"M\xe3e de Jesus e nossa m\xe3e, honrada com muitos t\xedtulos pelo mundo.",origem:"Nazar\xe9, Galileia \xb7 s\xe9culo I",festa:"1\xba de janeiro, Santa Maria, M\xe3e de Deus",padroeiro:["Brasil (Aparecida)","Am\xe9ricas (Guadalupe)"],rotuloPadroeiro:"Padroeira",imagem:(0,r.yQ)("Nossa senhora.webp"),posicaoImagem:"center 15%",estilo:"manto",cores:{principal:"#1F4E8C",secundaria:"#16365F",brilho:"#C9A54C"},paleta:{claro:{fundo:"#F4F1EA",cartao:"#FFFDF8",texto:"#1F2633",suave:"#5B6271",titulo:"#16325C",borda:"#DCD6C8",topo:"rgba(22, 54, 95, 0.94)"},escuro:{fundo:"#0A1424",cartao:"#122038",texto:"#E3EAF5",suave:"#9FB0C8",titulo:"#DCE8F8",borda:"#22385A",topo:"rgba(10, 20, 36, 0.94)"}},frase:{texto:"Fazei tudo o que ele vos disser.",autor:"Jo\xe3o 2,5"},historia:['Maria era uma jovem de Nazar\xe9 quando o anjo Gabriel lhe anunciou que seria a m\xe3e do Salvador. Respondeu com o seu "sim": "Eis aqui a serva do Senhor".',"Acompanhou Jesus do nascimento em Bel\xe9m \xe0 cruz no Calv\xe1rio. Nas bodas de Can\xe1, foi ela quem percebeu que faltava vinho e levou o pedido ao Filho.",'Aos p\xe9s da cruz, Jesus a entregou ao disc\xedpulo amado, e nele a toda a Igreja: "Eis a\xed tua m\xe3e". Por isso os crist\xe3os a chamam de m\xe3e.',"Ao longo dos s\xe9culos, Maria foi honrada com muitos t\xedtulos, ligados a apari\xe7\xf5es, a lugares e a verdades da f\xe9. Cada um mostra um jeito diferente do seu cuidado."],historias:{titulo:"Quando a M\xe3e apareceu",introducao:"Quatro apari\xe7\xf5es e encontros que marcaram a f\xe9 de milh\xf5es de pessoas:",itens:[{ilustracao:"aparecida",titulo:"Aparecida, 1717",texto:"Tr\xeas pescadores lan\xe7aram a rede no rio Para\xedba do Sul e tiraram o corpo de uma imagem da Imaculada Concei\xe7\xe3o. Na rede seguinte veio a cabe\xe7a, e depois tantos peixes que mal cabiam no barco. \xc9 a Padroeira do Brasil."},{ilustracao:"guadalupe",titulo:"Guadalupe, 1531",texto:"No M\xe9xico, ela pediu a S\xe3o Juan Diego que levasse ao bispo rosas colhidas no monte em pleno inverno. Quando ele abriu o manto diante do bispo, as rosas ca\xedram e a imagem de Maria estava estampada no tecido."},{ilustracao:"lourdes",titulo:"Lourdes, 1858",texto:'Na gruta de Massabielle, na Fran\xe7a, apareceu dezoito vezes a Santa Bernadete, uma menina pobre de 14 anos. Disse: "Eu sou a Imaculada Concei\xe7\xe3o". Da gruta brotou uma fonte que atrai peregrinos at\xe9 hoje.'},{ilustracao:"fatima",titulo:"F\xe1tima, 1917",texto:"Sobre uma azinheira em Portugal, apareceu a tr\xeas pastorinhos, L\xfacia, Francisco e Jacinta, do dia 13 de maio a outubro. Pediu ora\xe7\xe3o do ter\xe7o e convers\xe3o."}]},destaque:{tipo:"titulos",titulo:"Alguns t\xedtulos de Maria",introducao:"Uma s\xf3 M\xe3e, muitos nomes. Alguns que a Igreja celebra ao longo do ano:",itens:[{titulo:"Santa Maria, M\xe3e de Deus",data:"1\xba de janeiro",texto:"O t\xedtulo mais antigo: o filho de Maria \xe9 Deus feito homem."},{titulo:"Nossa Senhora do Carmo",data:"16 de julho",texto:"Ligada aos carmelitas e ao escapul\xe1rio que muitos cat\xf3licos usam."},{titulo:"Assun\xe7\xe3o de Nossa Senhora",data:"15 de agosto",texto:"Ao fim da vida terrena, Maria foi levada ao C\xe9u em corpo e alma."},{titulo:"Nossa Senhora Rainha",data:"22 de agosto",texto:"M\xe3e do Rei, ela \xe9 celebrada como Rainha do C\xe9u e da Terra."},{titulo:"Nossa Senhora das Dores",data:"15 de setembro",texto:"Lembra a m\xe3e que esteve de p\xe9 junto \xe0 cruz do Filho."},{titulo:"Imaculada Concei\xe7\xe3o",data:"8 de dezembro",texto:"Maria foi preservada do pecado original desde a sua concep\xe7\xe3o."}]},terco:!0,linhaDoTempo:[{ano:"431",texto:"O Conc\xedlio de \xc9feso proclama Maria M\xe3e de Deus."},{ano:"649",texto:"O Conc\xedlio de Latr\xe3o afirma a virgindade perp\xe9tua de Maria."},{ano:"1854",texto:"O papa Pio IX define o dogma da Imaculada Concei\xe7\xe3o."},{ano:"1950",texto:"O papa Pio XII define o dogma da Assun\xe7\xe3o."}],tituloLinhaDoTempo:"Os quatro dogmas marianos",oracao:{titulo:"Ave-Maria",texto:"Ave Maria, cheia de gra\xe7a,\no Senhor \xe9 convosco;\nbendita sois v\xf3s entre as mulheres\ne bendito \xe9 o fruto do vosso ventre, Jesus.\nSanta Maria, M\xe3e de Deus,\nrogai por n\xf3s, pecadores,\nagora e na hora de nossa morte.\nAm\xe9m."}}].map(a=>(0,s.A)((0,s.A)({},a),i[a.slug])),n=a=>t.find(o=>o.slug===a)}}]);
